    @staticmethod
    def parse(version):
        """Parse version string to a VersionInfo instance.

        >>> from semver import VersionInfo
        >>> VersionInfo.parse('3.4.5-pre.2+build.4')
        VersionInfo(major=3, minor=4, patch=5, \
prerelease='pre.2', build='build.4')

        :param version: version string
        :return: a :class:`VersionInfo` instance
        :rtype: :class:`VersionInfo`
        """
        return parse_version_info(version)

    def bump_major(self):
        """Return a new VersionInfo with the major component incremented."""
        return VersionInfo(
            self._major + 1, 0, 0,
            prerelease=None, build=None
        )

    def bump_minor(self):
        """Return a new VersionInfo with the minor component incremented."""
        return VersionInfo(
            self._major, self._minor + 1, 0,
            prerelease=None, build=None
        )

    def bump_patch(self):
        """Return a new VersionInfo with the patch component incremented."""
        return VersionInfo(
            self._major, self._minor, self._patch + 1,
            prerelease=None, build=None
        )

    def bump_prerelease(self, token='rc'):
        """Return a new VersionInfo with the prerelease component incremented."""
        if self._prerelease is None:
            new_prerelease = token + '.0'
        else:
            new_prerelease = _increment_string(self._prerelease)
        return VersionInfo(
            self._major, self._minor, self._patch,
            prerelease=new_prerelease, build=self._build
        )

    def bump_build(self, token='build'):
        """Return a new VersionInfo with the build component incremented."""
        if self._build is None:
            new_build = token + '.0'
        else:
            new_build = _increment_string(self._build)
        return VersionInfo(
            self._major, self._minor, self._patch,
            prerelease=self._prerelease, build=new_build
        )

    def replace(self, **kwargs):
        """Return a new VersionInfo with specified components replaced.

        :param kwargs: keyword arguments for components to replace (major, minor, 
                       patch, prerelease, build)
        :return: a new :class:`VersionInfo` instance with replaced components
        :rtype: :class:`VersionInfo`
        """
        return VersionInfo(
            kwargs.get('major', self._major),
            kwargs.get('minor', self._minor),
            kwargs.get('patch', self._patch),
            kwargs.get('prerelease', self._prerelease),
            kwargs.get('build', self._build)
        )
